const results = [];

for (const item of $input.all()) {
  const place = item.json;

  results.push({
    json: {
      name: place.title || "N/A",
      address: place.address || "N/A",
      rating: place.totalScore ?? "N/A",
      review_count: place.reviewsCount ?? 0,
      has_website: place.website ? true : false,
      website: place.website || "No website"
    }
  });
}

return results;

